def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    return np.where(remaining >= 0, -remaining, -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    ratio = remaining / (item + 1e-8)
    return np.where(valid, -np.power(ratio + 1.0, 2.0) - (1.0 / (remaining + 1e-8)), -np.inf)

def priority(item: float, bins: np.ndarray) -> np.ndarray:
    remaining = bins - item
    valid = remaining >= 0
    ratio = remaining / (item + 1e-8)
    return np.where(valid, -np.exp(ratio) - (1.0 / np.sqrt(remaining + 1e-8)), -np.inf)
